actions.script:

def temp1 = ec.entity.find("automobile.Bike").condition("brand" , "ducati").condition("cylinderEnumId","350cc").one()
ec.logger.info("---------------------------Found Bike ${temp1?.brand}-------------------------------------") 










def temp3 = ec.entity.find("mantle.party.Party").orderBy("-partyId").limit(5).list()

temp3.each{
    e -> ec.logger.info("==========================  ${e.partyId}  ${e.pseudoId} =======================")
}
